function user(){if(empty($_SESSION['usuario_id']))out(['exito'=>false,'mensaje'=>'Iniciá sesión para continuar.'],401);return (int)$_SESSION['usuario_id'];}
function admin(){user();if(($_SESSION['usuario_rol']??'socio')!=='encargado')out(['exito'=>false,'mensaje'=>'Acceso exclusivo para encargados.'],403);}
