case 'mis_pagos':$uid=user();$q=$d->prepare('SELECT concepto,monto,pago_ref,estado,creado,revisado FROM pagos WHERE usuario_id=:u ORDER BY creado DESC');$q->execute([':u'=>$uid]);$q2=$d->prepare('SELECT cuota_hasta,plan,alcance,sede FROM usuarios WHERE id=:u');$q2->execute([':u'=>$uid]);out(['exito'=>true,'pagos'=>$q->fetchAll(),'socio'=>$q2->fetch()]);
case 'credencial_verificar':$code=trim($in['codigo']??'');$parts=explode('|',$code);if(count($parts)!==5||$parts[0]!=='AERUS')out(['exito'=>false,'mensaje'=>'QR no válido.']);[, $numero,$plan,$alcance,$firma]=$parts;if(!preg_match('/^AER-(\d{5,})$/',$numero,$m))out(['exito'=>false,'mensaje'=>'Formato de credencial inválido.']);$uid=(int)$m[1];$q=$d->prepare("SELECT id,nombre,apellido,plan,alcance,sede,cuota_hasta FROM usuarios WHERE id=:u");$q->execute([':u'=>$uid]);$u=$q->fetch();if(!$u)out(['exito'=>false,'mensaje'=>'Socio no encontrado.']);$q=$d->prepare("SELECT concepto FROM pagos WHERE usuario_id=:u AND estado='aprobado' AND concepto LIKE 'plan:%' ORDER BY creado DESC LIMIT 1");$q->execute([':u'=>$uid]);$p=$q->fetch();if(!$p)out(['exito'=>true,'valido'=>false,'mensaje'=>'No hay un plan aprobado.','nombre'=>$u['nombre'].' '.$u['apellido']]);$secret=getenv('AERUS_QR_SECRET')?:'cambiar-esta-clave-por-una-frase-larga';$expected=substr(hash_hmac('sha256',$numero.'|'.$p['concepto'],$secret),0,16);$firmaValida=hash_equals($expected,$firma)&&$p['concepto']==="plan:$plan:$alcance";$alDia=!empty($u['cuota_hasta'])&&$u['cuota_hasta']>=date('Y-m-d');out(['exito'=>true,'valido'=>$firmaValida&&$alDia,'firma_valida'=>$firmaValida,'al_dia'=>$alDia,'nombre'=>$u['nombre'].' '.$u['apellido'],'plan'=>$plan,'alcance'=>$alcance,'sede'=>$u['sede'],'cuota_hasta'=>$u['cuota_hasta'],'mensaje'=>$firmaValida?($alDia?'Credencial vigente.':'Cuota vencida.'):'Firma QR inválida.']);
