case 'comentarios':$q=$d->query("SELECT c.tipo,c.referencia,c.calificacion,c.comentario,c.creado,u.nombre FROM comentarios c JOIN usuarios u ON u.id=c.usuario_id WHERE c.estado='aprobado' ORDER BY c.creado DESC LIMIT 100");out(['exito'=>true,'comentarios'=>$q->fetchAll()]);
case 'admin_comentarios':admin();$q=$d->query("SELECT c.id,c.tipo,c.referencia,c.calificacion,c.comentario,c.creado,u.nombre,u.apellido FROM comentarios c JOIN usuarios u ON u.id=c.usuario_id WHERE c.estado='pendiente' ORDER BY c.creado");out(['exito'=>true,'comentarios'=>$q->fetchAll()]);
case 'resolver_comentario':admin();$id=(int)($in['id']??0);$estado=$in['estado']??'';if(!in_array($estado,['aprobado','rechazado'],true))out(['exito'=>false,'mensaje'=>'Estado inválido.'],400);$q=$d->prepare('UPDATE comentarios SET estado=:e WHERE id=:id');$q->execute([':e'=>$estado,':id'=>$id]);out(['exito'=>true,'mensaje'=>'Comentario actualizado.']);
case 'contacto':$nombre=trim($in['nombre']??'');$email=trim($in['email']??'');$mensaje=trim($in['mensaje']??'');if(!$nombre||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($mensaje)<10||strlen($mensaje)>3000)out(['exito'=>false,'mensaje'=>'Revisá los datos del formulario.'],400);$q=$d->prepare('INSERT INTO mensajes_contacto(nombre,email,asunto,mensaje) VALUES(:n,:e,:a,:m)');$q->execute([':n'=>$nombre,':e'=>$email,':a'=>substr(trim($in['asunto']??'Consulta'),0,150),':m'=>$mensaje]);out(['exito'=>true,'mensaje'=>'Mensaje enviado. El equipo del club podrá responderte por email.']);
case 'reservar_clase':$uid=user();$clase=(int)($in['clase_id']??0);$d->beginTransaction();$q=$d->prepare('SELECT cupo, (SELECT COUNT(*) FROM reservas r WHERE r.clase_id=c.id AND r.estado<>\'cancelada\') ocupados FROM clases c WHERE id=:id AND fecha>=NOW() FOR UPDATE');$q->execute([':id'=>$clase]);$c=$q->fetch();if(!$c){$d->rollBack();out(['exito'=>false,'mensaje'=>'La clase no existe o ya pasó.'],404);}if($c['ocupados']>=$c['cupo']){$d->rollBack();out(['exito'=>false,'mensaje'=>'No quedan cupos.'],409);}$q=$d->prepare('SELECT id FROM reservas WHERE clase_id=:c AND usuario_id=:u AND estado<>\'cancelada\'');$q->execute([':c'=>$clase,':u'=>$uid]);if($q->fetch()){$d->rollBack();out(['exito'=>false,'mensaje'=>'Ya reservaste esta clase.'],409);}$q=$d->prepare('INSERT INTO reservas(clase_id,usuario_id) VALUES(:c,:u)');$q->execute([':c'=>$clase,':u'=>$uid]);$d->commit();out(['exito'=>true,'mensaje'=>'Clase reservada. ¡Te esperamos!']);
case 'clases':$q=$d->query("SELECT c.*, (SELECT COUNT(*) FROM reservas r WHERE r.clase_id=c.id AND r.estado<>'cancelada') ocupados FROM clases c WHERE fecha>=NOW() ORDER BY fecha LIMIT 50");out(['exito'=>true,'clases'=>$q->fetchAll()]);
case 'eventos':$q=$d->query('SELECT * FROM eventos WHERE fecha>=CURDATE() ORDER BY fecha LIMIT 100');out(['exito'=>true,'eventos'=>$q->fetchAll()]);
case 'recuperar_solicitar':$email=trim($in['email']??'');if(filter_var($email,FILTER_VALIDATE_EMAIL)){$q=$d->prepare('SELECT id,nombre FROM usuarios WHERE email=:e');$q->execute([':e'=>$email]);$u=$q->fetch();if($u){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$q=$d->prepare('INSERT INTO recuperaciones(usuario_id,token_hash,vence) VALUES(:u,:h,DATE_ADD(NOW(),INTERVAL 30 MINUTE))');$q->execute([':u'=>$u['id'],':h'=>$hash]);$base=(isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost');$path=rtrim(dirname(dirname($_SERVER['SCRIPT_NAME']??'/')),'/');$url=$base.$path.'/pages/recuperar.html?token='.urlencode($token);$sent=@mail($email,'Recuperación de contraseña - Aerus Club',"Hola {$u['nombre']},\n\nPara elegir una nueva contraseña, abrí este enlace dentro de los próximos 30 minutos:\n$url\n\nSi no solicitaste este cambio, ignorá el mensaje.",'From: no-reply@aerusclub.com');if(!$sent)error_log('Aerus: mail() no está configurado para enviar recuperación a '.$email);}}out(['exito'=>true,'mensaje'=>'Si el correo está registrado y el servidor de correo está configurado, recibirás un enlace de recuperación.']);
