case 'perfil':$uid=user();$nombre=trim($in['nombre']??'');$apellido=trim($in['apellido']??'');$avatar=$in['avatar']??null;$pass=$in['password']??'';if($avatar!==null){if(!str_starts_with($avatar,'data:image/')||strlen($avatar)>1500000)out(['exito'=>false,'mensaje'=>'Imagen inválida o demasiado grande.'],400);$q=$d->prepare('UPDATE usuarios SET avatar=:a WHERE id=:u');$q->execute([':a'=>$avatar,':u'=>$uid]);$_SESSION['usuario_avatar']=$avatar;}if($nombre!==''){$q=$d->prepare('UPDATE usuarios SET nombre=:n,apellido=:a WHERE id=:u');$q->execute([':n'=>$nombre,':a'=>$apellido,':u'=>$uid]);$_SESSION['usuario_nombre']=$nombre;$_SESSION['usuario_apellido']=$apellido;}if($pass!==''){if(strlen($pass)<8)out(['exito'=>false,'mensaje'=>'La contraseña debe tener al menos 8 caracteres.'],400);$q=$d->prepare('UPDATE usuarios SET password=:p WHERE id=:u');$q->execute([':p'=>password_hash($pass,PASSWORD_DEFAULT),':u'=>$uid]);}out(['exito'=>true,'mensaje'=>'Perfil actualizado.']);
default:out(['exito'=>false,'mensaje'=>'Acción no válida.'],400);
}}catch(Throwable $e){if(isset($d)&&$d->inTransaction())$d->rollBack();error_log('Aerus API: '.$e->getMessage());out(['exito'=>false,'mensaje'=>'Ocurrió un error interno. Revisá la configuración de la base de datos.'],500);}
